        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        require(recipient != address(0));

        uint balBefore = address(c).balance;

        c.fallback{value: amount}();

        uint balAfterFund = address(c).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint recipientBalanceAfter = recipient.balance;

