            reverted
                ? (msg.sender != c.owner() && address(c).balance == balAfterFund)
                : (msg.sender == c.owner() && recipientBalanceAfter >= balBefore + amount && address(c).balance == 0)
        );
    }

    receive() external payable {}
}

