contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient, uint256 amount) public payable {
        // Fund the contract with an arbitrary amount.
        require(address(this).balance >= amount);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        uint256 cBalBefore = address(c).balance;
        uint256 recipientBalBefore = recipient.balance;

        bool reverted;
        if (caller == address(this)) {
            // Owner path: c.withdrawAll must succeed.
            c.withdrawAll(recipient);
            reverted = false;
        } else {
            // Non-owner path: c.withdrawAll must revert.
            (bool success, ) = address(c).call(
                abi.encodeWithSignature("withdrawAll(address)", recipient)
            );
            reverted = !success;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 recipientBalAfter = recipient.balance;

        if (reverted) {
            assert(cBalAfter == cBalBefore && recipientBalAfter == recipientBalBefore);
        } else {
            assert(cBalAfter == 0 && recipientBalAfter == recipientBalBefore + cBalBefore);
        }
    }

    receive() external payable {}
}

